xql_query:
// ============================================================
// Rule: TRD_VisionOne_Detection_High
// Vendor: Trend Micro
// Objective:
// Detect activity associated with TRD_VisionOne_Detection_High.
// Severity: SEV_040_HIGH
// Category: OTHER
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0002 - Execution
// Technique: T1064 - Scripting
// Technique: T1086 - PowerShell
// Technique: T1153 - Source
// Tactic: TA0001 - Initial Access
// Technique: T1078 - Valid Accounts

dataset = trend_micro_vision_one_raw
| filter cat = 70
| alter
    // ============ IDENTIFICAÇÃO ============
    alert_type        = coalesce(pname, alertprovider, "Vision One Detection"),
    alert_name        = coalesce(msg, category, description),
    trend_event_id    = eventid,
    trend_rule_id     = to_string(ruleId),
    trend_event_uuid  = uuid,
    trend_log_key     = logKey,
    trend_event_type  = event_type,
    severity_label    = "HIGH",
    severity_num      = cat,
    event_time        = eventTime,
    event_rt          = rt,

    // ============ HOST / ENDPOINT (campos dedicados da API) ============
    endpoint_hostname = coalesce(endpointhostname, shost, dhost),
    endpoint_ip       = arrayindex(regextract(to_string(endpointip), "\d{1,3}(?:\.\d{1,3}){3}"), 0),
    endpoint_guid     = endpointguid,
    endpoint_host_id  = hostId,
    endpoint_status   = endpointstatus,
    endpoint_mac      = endpointmacaddress,
    endpoint_os       = osName,

    // ============ USUÁRIO (regex tolerante a SISTEMA/SYSTEM/DOMAIN\user) ============
    user              = arrayindex(regextract(to_string(duser), "[\w\-\.\\\\@]+"), 0),

    // ============ WINDOWS EVENT ============
    win_event_id      = winEventId,
    win_event_groups  = groups,

    // ============ PROCESSO ============
    process_name      = coalesce(deviceprocessname, sproc),
    process_pid       = processPid,
    parent_pid        = parentPid,

    // ============ TAGS / MITRE ============
    all_tags          = arraystring(regextract(to_string(tags), "[A-Z]+\.[A-Z0-9\.]+"), ","),
    mitre_techniques  = arraystring(regextract(to_string(tags), "MITRE\.[A-Z0-9\.]+"), ","),
    xsae_tags         = arraystring(regextract(to_string(tags), "XSAE\.[A-Z0-9]+"), ","),

    // ============ CONTEXTO ADICIONAL ============
    product_name      = mpname,
    product_version   = mpver,
    detection_type    = detectiontype,
    activity          = activity,
    action_result     = actresult,
    domain_name       = domainname,
    blocking          = blocking,

    // ============ AUDIT LOG (quando aplicável) ============
    audit_action      = act,
    audit_app         = app,
    audit_category    = category,

    // ============ NETWORK (quando aplicável) ============
    src_ip            = src,
    dst_ip            = dst,
    src_port          = spt,
    dst_port          = dpt,
    direction         = direction,

    // ============ DEEP LINK PARA CONSOLE TREND (para ver remarks completo) ============
    trend_console_url = concat(
        "https://portal.xdr.trendmicro.com/index.html#/app/oat/detail/",
        coalesce(eventid, uuid, "unknown")
    )

| fields _time, event_time, event_rt, severity_label, severity_num,
         alert_type, alert_name, trend_event_id, trend_rule_id, trend_event_uuid, trend_event_type,
         endpoint_hostname, endpoint_ip, endpoint_guid, endpoint_host_id, endpoint_status, endpoint_os,
         user, win_event_id, win_event_groups,
         process_name, process_pid, parent_pid,
         all_tags, mitre_techniques, xsae_tags,
         product_name, product_version, detection_type, activity, action_result, domain_name, blocking,
         audit_action, audit_app, audit_category,
         src_ip, dst_ip, src_port, dst_port, direction,
         trend_console_url
